// Pseudo: pick defaults for missing fields based on version
function normalizeEvent(evt) {
  const v = evt.version || 1;
  const defaults = v >= 2 ? { device_firmware: 'unknown', telemetry_version: '1.0.0' } : {};
  return { ...defaults, ...evt, version: v };
}
```

